const isWithinOneStep = (coordinate: number, otherCoordinate: number): boolean =>
  Math.abs(otherCoordinate - coordinate) <= 1;

const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
  x === otherX && y === otherY;

const isNeighborOf = (cell: Cell, other: Cell): boolean => {
  const [x, y] = cell;
  const [otherX, otherY] = other;
  return (
    isWithinOneStep(x, otherX) &&
    isWithinOneStep(y, otherY) &&
    !isSameCell(cell, other)
  );
};

const countLivingNeighbors = (cell: Cell, livingCells: Cell[]): number =>
  livingCells.filter((other) => isNeighborOf(cell, other)).length;

const survives = (livingNeighbors: number): boolean =>
  livingNeighbors >= 2 && livingNeighbors <= 3;

const neighborsOf = ([x, y]: Cell): Cell[] => [
  [x - 1, y - 1],
  [x, y - 1],
  [x + 1, y - 1],
  [x - 1, y],
  [x + 1, y],
  [x - 1, y + 1],
  [x, y + 1],
  [x + 1, y + 1],
];

